#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

PACKAGE_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
RELEASE_VERSION=$(node -p 'require(process.argv[1]).version' "$PACKAGE_ROOT/package.json")
PROFILE_ID="wifi_on_off_plug"
SOURCE_CONTAINER=""
RESTORE_CONTAINER=""
SOURCE_VOLUME=""
RESTORE_VOLUME=""
QUALIFICATION_COMPLETE=0
GUI_MODE="${MATTER_GUI:-0}"
BLE_WIFI_MODE="${MATTER_BLE_WIFI:-0}"
SOAK_CYCLES="${MATTER_SOAK_CYCLES:-0}"
RESTART_CYCLES="${MATTER_RESTART_CYCLES:-1}"
DOCKER_BLE_ARGS=()

stop_container() {
  [[ -n "$1" ]] || return 0
  docker stop --time 10 "$1" >/dev/null 2>&1 || true
  docker rm --force "$1" >/dev/null 2>&1 || true
}

on_exit() {
  stop_container "$SOURCE_CONTAINER"
  stop_container "$RESTORE_CONTAINER"
  if (( ! QUALIFICATION_COMPLETE )) && [[ -n "$SOURCE_VOLUME" || -n "$RESTORE_VOLUME" ]]; then
    printf '\n  Qualification stopped before completion. Containers are stopped.\n'
    printf '  Preserved volumes for diagnosis: %s %s\n' "$SOURCE_VOLUME" "$RESTORE_VOLUME"
    printf '  Never start both volumes as controllers at the same time.\n'
  fi
}
trap on_exit EXIT INT TERM

require_command() {
  command -v "$1" >/dev/null 2>&1 || { printf 'Missing required command: %s\n' "$1" >&2; exit 1; }
}

physical_confirm() {
  if [[ "$GUI_MODE" == "1" ]]; then
    zenity --question --title="Matter hardware qualification" --text="$1" --width=520
  else
    confirm "$1"
  fi
}

capture_setup_payload() {
  if [[ "$GUI_MODE" == "1" ]]; then
    ONE_TIME_MATTER_SETUP_PAYLOAD=$(zenity --password --title="Matter setup payload" \
      --text="Scan or paste the TP-Link KP125M Matter setup payload. It is used once and never stored." --width=520)
  else
    ask_secret ONE_TIME_MATTER_SETUP_PAYLOAD "Scan or paste the Matter setup payload:"
  fi
}

capture_wifi_credentials() {
  if [[ "$GUI_MODE" == "1" ]]; then
    ONE_TIME_WIFI_SSID=$(zenity --entry --title="Wi-Fi network" \
      --text="Enter the 2.4 GHz Wi-Fi network name for the KP125M. It is used only for this attempt." --width=520)
    ONE_TIME_WIFI_PASSWORD=$(zenity --password --title="Wi-Fi password" \
      --text="Enter the Wi-Fi password. It is stored in a unique temporary slot and deleted after this attempt." --width=520)
  else
    ask ONE_TIME_WIFI_SSID "2.4 GHz Wi-Fi network name:"
    ask_secret ONE_TIME_WIFI_PASSWORD "Wi-Fi password:"
  fi
}

api_get() {
  curl --fail-with-body --silent --show-error \
    -H "Authorization: Bearer $SIDECAR_TOKEN" "$BASE_URL$1"
}

api_post() {
  curl --fail-with-body --silent --show-error \
    -H "Authorization: Bearer $SIDECAR_TOKEN" \
    -H "Content-Type: application/json" \
    --data "$2" "$BASE_URL$1"
}

wait_health() {
  local deadline=$((SECONDS + 90))
  while (( SECONDS < deadline )); do
    if curl --silent --fail "$BASE_URL/health" | jq -e '.ok == true' >/dev/null 2>&1; then return 0; fi
    sleep 1
  done
  docker logs "$ACTIVE_CONTAINER" >&2 || true
  printf 'Sidecar did not become healthy within 90 seconds.\n' >&2
  return 1
}

wait_state() {
  local wanted="$1" output="$2" deadline=$((SECONDS + 30)) value
  while (( SECONDS < deadline )); do
    api_get "/v1/matter/snapshot" > "$output"
    value=$(jq -r --arg node "$NODE_ID" --arg path "$ENDPOINT_ID/6/0" \
      '.nodes[] | select(.node_id == $node) | .attributes[$path]' "$output")
    [[ "$value" == "$wanted" ]] && return 0
    sleep 1
  done
  printf 'Timed out waiting for switch_on=%s.\n' "$wanted" >&2
  return 1
}

wait_node_absent() {
  local output="$1" deadline=$((SECONDS + 30))
  while (( SECONDS < deadline )); do
    api_get "/v1/matter/snapshot" > "$output"
    if jq -e --arg node "$NODE_ID" '[.nodes[] | select(.node_id == $node)] | length == 0' "$output" >/dev/null; then
      return 0
    fi
    sleep 1
  done
  printf 'Timed out waiting for node removal.\n' >&2
  return 1
}

invoke_command() {
  local command="$1" output="$2"
  api_post "/v1/commands/invoke" "$(jq -cn \
    --arg node "$NODE_ID" --argjson endpoint "$ENDPOINT_ID" --arg command "$command" \
    '{node_id:$node, endpoint_id:$endpoint, command:$command, args:{}}')" > "$output"
}

run_wizard() {

TOTAL_STAGES=9

if [[ "$GUI_MODE" == "1" ]]; then
  printf '\n  Physical Matter plug qualification · %s stages\n\n' "$TOTAL_STAGES"
else
  banner "Physical Matter plug qualification"
fi

stage "Device and release metadata"
say "This run targets the required Wi-Fi On/Off plug profile."
for command in docker curl jq openssl node npm; do require_command "$command"; done
[[ "$SOAK_CYCLES" =~ ^[0-9]+$ ]] && (( SOAK_CYCLES <= 10000 )) || { warn "MATTER_SOAK_CYCLES must be an integer from 0 to 10000."; exit 1; }
[[ "$RESTART_CYCLES" =~ ^[1-9][0-9]*$ ]] && (( RESTART_CYCLES <= 100 )) || { warn "MATTER_RESTART_CYCLES must be an integer from 1 to 100."; exit 1; }
[[ "$GUI_MODE" == "1" ]] && require_command zenity
docker info >/dev/null
if [[ "$BLE_WIFI_MODE" == "1" ]]; then
  [[ -S /run/dbus/system_bus_socket ]] || { warn "The host system D-Bus socket is unavailable."; exit 1; }
  DOCKER_BLE_ARGS=(
    --security-opt apparmor=piphi-matter-ble
    --volume /run/dbus:/run/dbus:ro
    --env MATTER_ENABLE_BLE=true
    --env NOBLE_BINDINGS=dbus
  )
fi
IMAGE="${MATTER_IMAGE:-piphi-matter-js-sidecar:qualification}"
EXPECTED_IMAGE_DIGEST="${MATTER_EXPECTED_IMAGE_DIGEST:-}"
[[ -z "$EXPECTED_IMAGE_DIGEST" || "$EXPECTED_IMAGE_DIGEST" =~ ^sha256:[a-f0-9]{64}$ ]] || {
  warn "MATTER_EXPECTED_IMAGE_DIGEST must be a sha256 digest."
  exit 1
}
RESOLVED_IMAGE_DIGEST=$(docker buildx imagetools inspect "$IMAGE" --format '{{.Manifest.Digest}}')
[[ "$RESOLVED_IMAGE_DIGEST" =~ ^sha256:[a-f0-9]{64}$ ]] || {
  warn "The registry did not return an immutable image digest for $IMAGE."
  exit 1
}
if [[ -n "$EXPECTED_IMAGE_DIGEST" && "$RESOLVED_IMAGE_DIGEST" != "$EXPECTED_IMAGE_DIGEST" ]]; then
  warn "Published image digest mismatch: expected $EXPECTED_IMAGE_DIGEST, resolved $RESOLVED_IMAGE_DIGEST."
  exit 1
fi
IMAGE_DIGEST="$RESOLVED_IMAGE_DIGEST"
EVIDENCE_LEVEL="candidate"
if [[ -n "$EXPECTED_IMAGE_DIGEST" ]]; then
  IMAGE="$IMAGE@$EXPECTED_IMAGE_DIGEST"
  EVIDENCE_LEVEL="published"
fi
docker pull "$IMAGE" >/dev/null
docker image inspect "$IMAGE" >/dev/null
LOCAL_IMAGE_ID=$(docker image inspect --format '{{.Id}}' "$IMAGE")
SERVER_ARCH=$(docker version --format '{{.Server.Arch}}')
IMAGE_INDEX=$(docker buildx imagetools inspect --raw "$IMAGE")
IMAGE_MEDIA_TYPE=$(jq -r '.mediaType' <<<"$IMAGE_INDEX")
if [[ "$IMAGE_MEDIA_TYPE" == "application/vnd.oci.image.index.v1+json" || "$IMAGE_MEDIA_TYPE" == "application/vnd.docker.distribution.manifest.list.v2+json" ]]; then
  PLATFORM_MANIFEST_DIGEST=$(jq -er --arg arch "$SERVER_ARCH" '.manifests[] | select(.platform.os == "linux" and .platform.architecture == $arch) | .digest' <<<"$IMAGE_INDEX" | head -n1)
else
  PLATFORM_MANIFEST_DIGEST="$IMAGE_DIGEST"
fi
[[ "$PLATFORM_MANIFEST_DIGEST" =~ ^sha256:[a-f0-9]{64}$ ]] || {
  warn "No linux/$SERVER_ARCH platform manifest exists in $IMAGE_DIGEST."
  exit 1
}
if [[ "$GUI_MODE" == "1" ]]; then
  OPERATOR="${QUAL_OPERATOR:?QUAL_OPERATOR is required in GUI mode}"
  DEVICE_VENDOR="${QUAL_VENDOR:?QUAL_VENDOR is required in GUI mode}"
  DEVICE_MODEL="${QUAL_MODEL:?QUAL_MODEL is required in GUI mode}"
  HARDWARE_REVISION="${QUAL_HARDWARE_REVISION:-unknown}"
  FIRMWARE_VERSION="${QUAL_FIRMWARE_VERSION:-unknown}"
  NETWORK_SUMMARY="${QUAL_NETWORK_SUMMARY:-Same-LAN Wi-Fi qualification; addresses redacted}"
else
  ask OPERATOR "Operator name:"
  ask DEVICE_VENDOR "Device vendor:"
  ask DEVICE_MODEL "Device model:"
  ask HARDWARE_REVISION "Hardware revision:"
  ask FIRMWARE_VERSION "Firmware version:"
  ask NETWORK_SUMMARY "Redacted host/LAN description (no addresses):"
fi
RUN_STARTED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
RUN_ID=$(date -u +%Y%m%dT%H%M%SZ)
WORKSPACE="$PACKAGE_ROOT/docs/qualification/${RUN_ID}-${PROFILE_ID}"
mkdir -p "$WORKSPACE"
chmod 700 "$WORKSPACE"
note "image: $IMAGE"
note "index digest: $IMAGE_DIGEST"
note "linux/$SERVER_ARCH manifest: $PLATFORM_MANIFEST_DIGEST (local image $LOCAL_IMAGE_ID)"
note "evidence level: $EVIDENCE_LEVEL"
note "evidence workspace: $WORKSPACE"

stage "Physical readiness"
if [[ "$BLE_WIFI_MODE" == "1" ]]; then
  step "Factory-reset the KP125M by holding its power button for at least 10 seconds."
  step "Wait until its LED flashes amber rapidly, then amber and blue for setup."
  step "Keep the printed 11-digit Matter code available; do not add the plug in Kasa."
else
  step "Confirm the plug is joined to the same Wi-Fi LAN as this host."
  step "Put the plug into Matter commissioning mode according to its vendor instructions."
fi
step "Confirm the host can reach the public DCL used for physical-device attestation."
step "Keep physical access to its button and load indicator for state confirmation."
if [[ "$BLE_WIFI_MODE" == "1" ]]; then
  physical_confirm "Has the KP125M been factory-reset and is its LED flashing for initial setup?" || { warn "Reset the device, then rerun the wizard."; exit 1; }
else
  physical_confirm "Is the TP-Link KP125M on this Wi-Fi LAN and in Matter commissioning mode?" || { warn "Prepare the device, then rerun the wizard."; exit 1; }
fi

stage "Start isolated controller"
SIDECAR_TOKEN=$(openssl rand -hex 32)
API_PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close()})')
BACKEND_PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close()})')
while [[ "$BACKEND_PORT" == "$API_PORT" ]]; do
  BACKEND_PORT=$(node -e 'const s=require("net").createServer();s.listen(0,"127.0.0.1",()=>{console.log(s.address().port);s.close()})')
done
SUFFIX="$$-${RUN_ID}"
SOURCE_CONTAINER="piphi-matter-hardware-${SUFFIX}"
SOURCE_VOLUME="piphi-matter-hardware-${SUFFIX}"
RESTORE_CONTAINER="${SOURCE_CONTAINER}-restore"
RESTORE_VOLUME="${SOURCE_VOLUME}-restore"
BASE_URL="http://127.0.0.1:$API_PORT"
ACTIVE_CONTAINER="$SOURCE_CONTAINER"
docker volume create "$SOURCE_VOLUME" >/dev/null
docker run --detach --name "$SOURCE_CONTAINER" --network host \
  "${DOCKER_BLE_ARGS[@]}" \
  --volume "$SOURCE_VOLUME:/var/lib/piphi/matter" \
  --env "PORT=$API_PORT" --env "MATTER_BACKEND_PORT=$BACKEND_PORT" \
  --env "PIPHI_MATTER_SIDECAR_TOKEN=$SIDECAR_TOKEN" \
  --env "MATTER_LOG_MANAGED_SERVER=false" \
  "$IMAGE" >/dev/null
wait_health
say "The isolated controller is healthy. Its token exists only in this process."

stage "Network preflight"
api_get "/v1/preflight" > "$WORKSPACE/preflight.json"
jq . "$WORKSPACE/preflight.json"
jq -e "if \"$BLE_WIFI_MODE\" == \"1\" then .ready_for_ble_wifi == true else .ready_for_on_network == true end" "$WORKSPACE/preflight.json" >/dev/null || {
  warn "Matter transport preflight failed; evidence was retained."
  exit 1
}
say "IPv6, selected-interface, and backend readiness passed."

stage "Commission device"
warn "The setup payload is hidden and will not be written to disk."
capture_setup_payload
ONE_TIME_MATTER_SETUP_PAYLOAD=$(printf '%s' "$ONE_TIME_MATTER_SETUP_PAYLOAD" | tr -d '[:space:]-')
[[ "$ONE_TIME_MATTER_SETUP_PAYLOAD" == MT:* || "$ONE_TIME_MATTER_SETUP_PAYLOAD" =~ ^[0-9]{11}$ || "$ONE_TIME_MATTER_SETUP_PAYLOAD" =~ ^[0-9]{21}$ ]] || {
  warn "The payload is not a recognized QR or manual Matter code."
  exit 1
}
if [[ "$BLE_WIFI_MODE" == "1" ]]; then
  capture_wifi_credentials
  [[ -n "$ONE_TIME_WIFI_SSID" && -n "$ONE_TIME_WIFI_PASSWORD" ]] || { warn "Wi-Fi network name and password are required."; exit 1; }
  printf '%s\0%s\0%s' "$ONE_TIME_MATTER_SETUP_PAYLOAD" "$ONE_TIME_WIFI_SSID" "$ONE_TIME_WIFI_PASSWORD" \
    | node -e 'let b=[];process.stdin.on("data",c=>b.push(c)).on("end",()=>{const [setup_payload,ssid,credentials]=Buffer.concat(b).toString().split("\0");process.stdout.write(JSON.stringify({setup_payload,ssid,credentials}))})' \
    | curl --fail-with-body --silent --show-error \
        -H "Authorization: Bearer $SIDECAR_TOKEN" -H "Content-Type: application/json" \
        --data-binary @- "$BASE_URL/v1/commission/wifi" > "$WORKSPACE/commission.json"
  unset ONE_TIME_MATTER_SETUP_PAYLOAD ONE_TIME_WIFI_SSID ONE_TIME_WIFI_PASSWORD
else
  printf '%s' "$ONE_TIME_MATTER_SETUP_PAYLOAD" \
    | jq -Rcn '{setup_payload:input,network_only:true}' \
    | curl --fail-with-body --silent --show-error \
        -H "Authorization: Bearer $SIDECAR_TOKEN" -H "Content-Type: application/json" \
        --data-binary @- "$BASE_URL/v1/commission/code" > "$WORKSPACE/commission.json"
  unset ONE_TIME_MATTER_SETUP_PAYLOAD
fi
NODE_ID=$(jq -er '.node_id' "$WORKSPACE/commission.json")
ENDPOINT_ID=$(jq -er '.endpoints[] | select(.capabilities | index("switch_on")) | .endpoint_id' "$WORKSPACE/commission.json" | head -n1)
[[ "$ENDPOINT_ID" =~ ^[0-9]+$ ]] || { warn "No negotiated On/Off endpoint was returned."; exit 1; }
api_get "/v1/matter/snapshot" > "$WORKSPACE/commissioned-snapshot.json"
CONTROLLER_IDENTITY_HASH=$(jq -er '.controller.identity_hash' "$WORKSPACE/commissioned-snapshot.json")
DETECTED_HARDWARE_REVISION=$(jq -r --arg node "$NODE_ID" '.nodes[] | select(.node_id == $node) | (.attributes["0/40/8"] // .attributes["0/40/7"] // empty)' "$WORKSPACE/commissioned-snapshot.json")
DETECTED_FIRMWARE_VERSION=$(jq -r --arg node "$NODE_ID" '.nodes[] | select(.node_id == $node) | (.attributes["0/40/10"] // .attributes["0/40/9"] // empty)' "$WORKSPACE/commissioned-snapshot.json")
VENDOR_ID=$(jq -er --arg node "$NODE_ID" '.nodes[] | select(.node_id == $node) | .attributes["0/40/2"]' "$WORKSPACE/commissioned-snapshot.json")
PRODUCT_ID=$(jq -er --arg node "$NODE_ID" '.nodes[] | select(.node_id == $node) | .attributes["0/40/4"]' "$WORKSPACE/commissioned-snapshot.json")
if [[ "${HARDWARE_REVISION,,}" == *"don't know"* || "${HARDWARE_REVISION,,}" == "unknown" ]]; then
  HARDWARE_REVISION="$DETECTED_HARDWARE_REVISION"
fi
if [[ "${FIRMWARE_VERSION,,}" == *"don't know"* || "${FIRMWARE_VERSION,,}" == "unknown" ]]; then
  FIRMWARE_VERSION="$DETECTED_FIRMWARE_VERSION"
fi
[[ -n "$HARDWARE_REVISION" && -n "$FIRMWARE_VERSION" ]] || {
  warn "The device did not expose complete hardware/firmware metadata; obtain it from the vendor app before qualifying."
  exit 1
}
note "node: $NODE_ID endpoint: $ENDPOINT_ID controller: $CONTROLLER_IDENTITY_HASH"
note "detected hardware: $HARDWARE_REVISION firmware: $FIRMWARE_VERSION"

stage "Control and subscription state"
invoke_command turn_on "$WORKSPACE/turn-on.json"
wait_state true "$WORKSPACE/state-on.json"
physical_confirm "The controller reports ON. Is the physical plug visibly ON?" || { warn "Physical state did not match subscribed state."; exit 1; }
invoke_command turn_off "$WORKSPACE/turn-off.json"
wait_state false "$WORKSPACE/state-off.json"
physical_confirm "The controller reports OFF. Is the physical plug visibly OFF?" || { warn "Physical state did not match subscribed state."; exit 1; }
say "Both commands and subscription-backed state transitions passed."
if (( SOAK_CYCLES > 0 )); then
  SOAK_STARTED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
  for cycle in $(seq 1 "$SOAK_CYCLES"); do
    invoke_command turn_on /dev/null
    wait_state true "$WORKSPACE/soak-state.json"
    invoke_command turn_off /dev/null
    wait_state false "$WORKSPACE/soak-state.json"
  done
  SOAK_COMPLETED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
  jq -n --argjson cycles "$SOAK_CYCLES" --arg started "$SOAK_STARTED_AT" --arg completed "$SOAK_COMPLETED_AT" \
    '{schema_version:1,cycles:$cycles,commands:($cycles*2),subscription_convergences:($cycles*2),final_state:false,started_at:$started,completed_at:$completed}' \
    > "$WORKSPACE/control-soak.json"
  physical_confirm "After $SOAK_CYCLES control cycles, is the physical device visibly OFF?" || { warn "Soak final state did not match the physical device."; exit 1; }
  say "$SOAK_CYCLES repeated On/Off cycles and subscription convergences passed."
fi

stage "Sidecar restart recovery"
RESTART_STARTED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
for cycle in $(seq 1 "$RESTART_CYCLES"); do
  docker restart "$SOURCE_CONTAINER" >/dev/null
  wait_health
  wait_state false "$WORKSPACE/restart-state.json"
  invoke_command turn_on "$WORKSPACE/restart-turn-on.json"
  wait_state true "$WORKSPACE/restart-state-on.json"
  invoke_command turn_off "$WORKSPACE/restart-turn-off.json"
  wait_state false "$WORKSPACE/restart-state-off.json"
done
RESTART_COMPLETED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
jq -n --argjson cycles "$RESTART_CYCLES" --arg started "$RESTART_STARTED_AT" --arg completed "$RESTART_COMPLETED_AT" \
  '{schema_version:1,cycles:$cycles,health_recoveries:$cycles,control_round_trips:$cycles,final_state:false,started_at:$started,completed_at:$completed}' \
  > "$WORKSPACE/restart-soak.json"
physical_confirm "After $RESTART_CYCLES sidecar restart and control cycles, is the physical device visibly OFF?" || { warn "Restart recovery failed physical confirmation."; exit 1; }
say "$RESTART_CYCLES sidecar restarts preserved identity, subscription state, and control."

stage "Restore controller and decommission"
physical_confirm "Proceed with quiesced backup, empty-volume restore, and final fabric removal?" || {
  warn "A complete qualification requires restore and decommission evidence."
  exit 1
}
api_post "/v1/admin/backup/quiesce" '{"confirmation":"quiesce-matter-controller"}' > "$WORKSPACE/backup-quiesce.json"
docker volume create "$RESTORE_VOLUME" >/dev/null
docker run --rm --user 0 --entrypoint sh \
  --volume "$SOURCE_VOLUME:/source:ro" --volume "$RESTORE_VOLUME:/target" \
  "$IMAGE" -c 'cp -a /source/. /target/ && rm -rf -- /target/.piphi-controller.lock' >/dev/null
stop_container "$SOURCE_CONTAINER"
ACTIVE_CONTAINER="$RESTORE_CONTAINER"
docker run --detach --name "$RESTORE_CONTAINER" --network host \
  "${DOCKER_BLE_ARGS[@]}" \
  --volume "$RESTORE_VOLUME:/var/lib/piphi/matter" \
  --env "PORT=$API_PORT" --env "MATTER_BACKEND_PORT=$BACKEND_PORT" \
  --env "PIPHI_MATTER_SIDECAR_TOKEN=$SIDECAR_TOKEN" \
  --env "MATTER_LOG_MANAGED_SERVER=false" \
  "$IMAGE" >/dev/null
wait_health
wait_state false "$WORKSPACE/restored-snapshot.json"
RESTORED_IDENTITY_HASH=$(jq -er '.controller.identity_hash' "$WORKSPACE/restored-snapshot.json")
[[ "$RESTORED_IDENTITY_HASH" == "$CONTROLLER_IDENTITY_HASH" ]] || { warn "Restored controller identity changed."; exit 1; }
invoke_command turn_on "$WORKSPACE/restored-turn-on.json"
wait_state true "$WORKSPACE/restored-state-on.json"
physical_confirm "Did the restored controller turn the physical plug ON?" || { warn "Restore control failed physical confirmation."; exit 1; }
invoke_command turn_off "$WORKSPACE/restored-turn-off.json"
wait_state false "$WORKSPACE/restored-state-off.json"
physical_confirm "Decommission node $NODE_ID now? This removes the controller fabric from the plug." || exit 1
api_post "/v1/nodes/$NODE_ID/decommission" "$(jq -cn --arg node "$NODE_ID" '{confirm_node_id:$node}')" > "$WORKSPACE/decommission.json"
wait_node_absent "$WORKSPACE/final-snapshot.json"
physical_confirm "Power-cycle the device without factory-resetting it, wait for it to reconnect, then continue with on-network decommission verification." || exit 1
api_get "/v1/discovery/commissionables?timeout_seconds=20" \
  | jq 'map({instance_name,vendor_id,product_id,device_type,long_discriminator,commissioning_mode,address_count:(.addresses|length),metadata:{}})' \
  > "$WORKSPACE/post-decommission-discovery.json"
if jq -e --argjson vendor "$VENDOR_ID" --argjson product "$PRODUCT_ID" \
  'any(.[]; .vendor_id == $vendor and .product_id == $product and .commissioning_mode == 1 and .address_count > 0)' \
  "$WORKSPACE/post-decommission-discovery.json" >/dev/null; then
  say "The device advertises on-network commissioning mode with no controller node remaining."
elif ! physical_confirm "On-network discovery was inconclusive. Does the device physically indicate it is uncommissioned or ready to pair again?"; then
  warn "Controller removal completed, but physical decommissioning was not confirmed."
  exit 1
fi
say "Restore identity, restored control, and node-scoped decommissioning passed."

stage "Validate and record evidence"
RUN_COMPLETED_AT=$(date -u +%Y-%m-%dT%H:%M:%S.000Z)
REPORT_PATH="$WORKSPACE/report.json"
if [[ "$BLE_WIFI_MODE" == "1" ]]; then
  QUALIFICATION_STEPS='["network_preflight","ble_wifi_provisioning","commission","capability_negotiation","turn_on","subscription_state_on","turn_off","subscription_state_off","sidecar_restart_recovery","controller_restore_recovery","decommission"]'
else
  QUALIFICATION_STEPS='["network_preflight","commission","capability_negotiation","turn_on","subscription_state_on","turn_off","subscription_state_off","sidecar_restart_recovery","controller_restore_recovery","decommission"]'
fi
EVIDENCE_ARTIFACTS=$(jq -cn --arg workspace "docs/qualification/$(basename "$WORKSPACE")" \
  '[$workspace+"/preflight.json",$workspace+"/commission.json",$workspace+"/restored-snapshot.json",$workspace+"/decommission.json",$workspace+"/post-decommission-discovery.json",$workspace+"/restart-soak.json"]')
if (( SOAK_CYCLES > 0 )); then
  QUALIFICATION_STEPS=$(jq -c '. + ["control_soak"]' <<<"$QUALIFICATION_STEPS")
  EVIDENCE_ARTIFACTS=$(jq -c --arg workspace "docs/qualification/$(basename "$WORKSPACE")" '. + [$workspace+"/control-soak.json"]' <<<"$EVIDENCE_ARTIFACTS")
fi
jq -n \
  --arg release "$RELEASE_VERSION" --arg profile "$PROFILE_ID" \
  --arg vendor "$DEVICE_VENDOR" --arg model "$DEVICE_MODEL" \
  --arg hardware "$HARDWARE_REVISION" --arg firmware "$FIRMWARE_VERSION" \
  --arg evidence_level "$EVIDENCE_LEVEL" \
  --arg digest "$IMAGE_DIGEST" --arg platform_digest "$PLATFORM_MANIFEST_DIGEST" \
  --arg architecture "$SERVER_ARCH" --arg local_image_id "$LOCAL_IMAGE_ID" \
  --arg host "$(uname -srmo)" --arg network "$NETWORK_SUMMARY" \
  --arg controller "$CONTROLLER_IDENTITY_HASH" --arg operator "$OPERATOR" \
  --arg started "$RUN_STARTED_AT" --arg completed "$RUN_COMPLETED_AT" \
  --arg workspace "docs/qualification/$(basename "$WORKSPACE")" \
  --argjson steps "$QUALIFICATION_STEPS" \
  --argjson artifacts "$EVIDENCE_ARTIFACTS" \
  '{schema_version:1,release:$release,profile_id:$profile,result:"qualified",evidence_level:$evidence_level,
    device:{vendor:$vendor,model:$model,hardware_revision:$hardware,firmware_version:$firmware,transport:"wifi_on_network"},
    environment:{image_digest:$digest,platform_manifest_digest:$platform_digest,architecture:$architecture,local_image_id:$local_image_id,host_os:$host,network_summary:$network},
    controller_identity_hash:$controller,
    run:{operator:$operator,started_at:$started,completed_at:$completed},
    steps:$steps | map({id:.,status:"pass",evidence:("See "+$workspace+" redacted artifacts")}),
    evidence_artifacts:$artifacts}' \
  > "$REPORT_PATH"
npm --prefix "$PACKAGE_ROOT" run validate:hardware-report -- "$REPORT_PATH"
REPORT_RELATIVE="docs/qualification/$(basename "$WORKSPACE")/report.json"
LEDGER="$PACKAGE_ROOT/docs/hardware-qualification.json"
PUBLICATION_DIGEST=$(jq -r '.publication.index_digest // empty' "$LEDGER")
LEDGER_TMP=$(mktemp)
  jq --arg profile "$PROFILE_ID" --arg report "$REPORT_RELATIVE" \
    --arg vendor "$DEVICE_VENDOR" --arg model "$DEVICE_MODEL" --arg firmware "$FIRMWARE_VERSION" \
    --arg digest "$IMAGE_DIGEST" --arg platform_digest "$PLATFORM_MANIFEST_DIGEST" \
    --arg evidence_level "$EVIDENCE_LEVEL" --arg publication_digest "$PUBLICATION_DIGEST" --arg completed "$RUN_COMPLETED_AT" \
    --argjson steps "$QUALIFICATION_STEPS" \
  '(.profiles[] | select(.id == $profile)) |= (
    .status = "qualified" | del(.blocker)
    | .evidence += [{report:$report,vendor:$vendor,model:$model,firmware_version:$firmware,image_digest:$digest,platform_manifest_digest:$platform_digest,evidence_level:$evidence_level,completed_at:$completed,steps:$steps}]
    | if $evidence_level == "published" and $digest == $publication_digest
      then .production_status = "qualified" | del(.production_blocker)
      else . end
  )' \
  "$LEDGER" > "$LEDGER_TMP"
cat "$LEDGER_TMP" > "$LEDGER"
rm -f "$LEDGER_TMP"
npm --prefix "$PACKAGE_ROOT" run validate
stop_container "$RESTORE_CONTAINER"
docker volume rm "$SOURCE_VOLUME" "$RESTORE_VOLUME" >/dev/null
SOURCE_VOLUME=""; RESTORE_VOLUME=""; QUALIFICATION_COMPLETE=1
say "Qualification passed and the hardware ledger now references the redacted report."
note "Review and commit: $WORKSPACE and $LEDGER"

finish
}

run_wizard "$@"; exit
